  b.x += (h.x - 0.5) * 0.08;
  b.y += (h.y - 0.5) * 0.05;
  b.z *= (0.82 + hash12(vec2(float(i) * 3.1 + 0.5, seed)) * 0.36) * (1.0 + uPulse * 0.06);
